    16  #define MCINST_CACHE (ARR_SIZE(mcInst->Operands) - 1)
    17
    18  void MCInst_Init(MCInst *inst)
    19  {
    20          unsigned int i;
    21
    22          for (i = 0; i < 48; i++) {
    23                  inst->Operands[i].Kind = kInvalid;
    24          }
    25
    26          inst->Opcode = 0;
    27          inst->OpcodePub = 0;
    28          inst->size = 0;
    29          inst->has_imm = false;
    30          inst->op1_size = 0;
    31          inst->writeback = false;
    32          inst->ac_idx = 0;
    33          inst->popcode_adjust = 0;
    34          inst->assembly[0] = '\0';
    35          inst->wasm_data.type = WASM_OP_INVALID;
    36  }
    37
    38  void MCInst_clear(MCInst *inst)
    39  {
    40          inst->size = 0;
    41  }
    42
    43  // do not free @Op
    44  void MCInst_insert0(MCInst *inst, int index, MCOperand *Op)
    45  {
    46          int i;
    47
    48          for(i = inst->size; i > index; i--)
    49                  //memcpy(&(inst->Operands[i]), &(inst->Operands[i-1]), sizeof(MCOperand));
    50                  inst->Operands[i] = inst->Operands[i-1];
    51
    52          inst->Operands[index] = *Op;
    53          inst->size++;
    54  }
    55
    56  void MCInst_setOpcode(MCInst *inst, unsigned Op)
    57  {
    58          inst->Opcode = Op;
    59  }
    60
    61  void MCInst_setOpcodePub(MCInst *inst, unsigned Op)
    62  {
    63          inst->OpcodePub = Op;
    64  }
