    66  unsigned MCInst_getOpcode(const MCInst *inst)
    67  {
    68          return inst->Opcode;
    69  }
    70
    71  unsigned MCInst_getOpcodePub(const MCInst *inst)
    72  {
    73          return inst->OpcodePub;
    74  }
    75
    76  MCOperand *MCInst_getOperand(MCInst *inst, unsigned i)
    77  {
    78          return &inst->Operands[i];
    79  }
    80
    81  unsigned MCInst_getNumOperands(const MCInst *inst)
    82  {
    83          return inst->size;
    84  }
    85
    86  // This addOperand2 function doesnt free Op
    87  void MCInst_addOperand2(MCInst *inst, MCOperand *Op)
    88  {
    89          inst->Operands[inst->size] = *Op;
    90
    91          inst->size++;
    92  }
