   146  MCOperand *MCOperand_CreateReg1(MCInst *mcInst, unsigned Reg)
   147  {
   148          MCOperand *op = &(mcInst->Operands[MCINST_CACHE]);
   149
   150          op->Kind = kRegister;
   151          op->RegVal = Reg;
   152
   153          return op;
   154  }
   155
   156  void MCOperand_CreateReg0(MCInst *mcInst, unsigned Reg)
   157  {
   158          MCOperand *op = &(mcInst->Operands[mcInst->size]);
   159          mcInst->size++;
   160
   161          op->Kind = kRegister;
   162          op->RegVal = Reg;
   163  }
   164
   165  MCOperand *MCOperand_CreateImm1(MCInst *mcInst, int64_t Val)
   166  {
   167          MCOperand *op = &(mcInst->Operands[MCINST_CACHE]);
   168
   169          op->Kind = kImmediate;
   170          op->ImmVal = Val;
   171
   172          return op;
   173  }
   174
   175  void MCOperand_CreateImm0(MCInst *mcInst, int64_t Val)
